function getPosition(){return new Promise((resolve,reject)=>{if(!navigator.geolocation){reject(new Error('Denne nettleseren støtter ikke posisjon. Bruk en annen nettleser eller kontakt administrator.'));return}navigator.geolocation.getCurrentPosition(resolve,error=>{const messages={1:'Posisjon er blokkert. Du må tillate posisjon for Apart Tid. Se «Hjelp med posisjon» nedenfor.',2:'Posisjonen kunne ikke finnes. Slå på posisjonstjenester og prøv nær et vindu. Kontakt administrator hvis det fortsatt ikke fungerer.',3:'Det tok for lang tid å finne posisjonen. Prøv igjen nær et vindu.'};reject(new Error(messages[error.code]||'Posisjonen kunne ikke hentes. Se hjelp med posisjon.'))},{enableHighAccuracy:true,timeout:20000,maximumAge:0})})}
