async function clockWithPosition(){
  if(clockBusy||!clockState||(!clockState.open_entry&&clockState.clock_in_gate?.allowed===false))return;
  const expectedEntry=clockState.open_entry?.id||null,action=expectedEntry?'clock_out':'clock_in';
  clockBusy=true;renderClock();setClockMessage('Kontrollerer posisjon. Tillat posisjon hvis enheten spør.');
  let submitting=false;
  try{
    if(!navigator.onLine)throw new Error('Du er uten internett. Koble til nettet og prøv igjen.');
    const fresh=await authenticated('/functions/v1/time-clock');
    clockState=fresh;
    if((fresh.open_entry?.id||null)!==expectedEntry){setClockMessage('Stemplingsstatusen er oppdatert. Kontroller statusen og trykk på nytt.');return}
    if(!expectedEntry&&fresh.clock_in_gate?.allowed===false){setClockMessage(fresh.clock_in_gate.message,'error');return}
    const position=await getPosition();
    submitting=true;
    const data=await authenticated('/functions/v1/time-clock',{method:'POST',body:{action,open_entry_id:expectedEntry,...positionBody(position)}});
    clockState.open_entry=action==='clock_in'?data.entry:null;
    const message=action==='clock_in'?`Du er stemplet inn kl. ${formatTime(data.entry.started_at)}.`:`Du er stemplet ut kl. ${formatTime(data.entry.ended_at)}.`;
    const refreshed=await loadClock();
    setClockMessage(message+(refreshed?'':' Timelisten kunne ikke oppdateres. Trykk Oppdater status.'),'success');
  }catch(error){
    if(!submitting)setClockMessage('Stemplingen er ikke registrert. '+error.message,'error');
    else{
      await loadClock();
      const rejected=error.status>=400&&error.status<500;
      setClockMessage(rejected?'Stemplingen er ikke registrert. '+error.message:'Kunne ikke bekrefte stemplingen. Kontroller statusen eller trykk Oppdater status før du prøver igjen. '+error.message,'error');
    }
  }finally{clockBusy=false;renderClock()}
}
