function renderEmployees(){const term=$('#search').value.trim().toLowerCase();const items=employees.filter(x=>[x.employee_number,x.full_name,x.email,x.phone_number].join(' ').toLowerCase().includes(term));$('#empty').classList.toggle('hidden',items.length>0);$('#rows').innerHTML=items.map(x=>`<tr class="${x.active?'':'inactive'}"><td><div class="person"><span class="avatar">${initials(x.full_name)}</span><strong>${escapeHtml(x.full_name)}</strong></div></td><td>${escapeHtml(x.employee_number)}</td><td>${escapeHtml(x.email)}<br><small>${escapeHtml(x.phone_number||'Ingen telefon')} · ${x.invited_at?'Invitert':'Ikke invitert'}</small></td><td>${roleText(x.role)}</td><td>${employeeWorkStatus(x)}</td><td><span class="status ${x.active?'active':''}">${x.active?'Aktiv':'Inaktiv'}</span></td><td><div class="actions">${x.active&&!x.invited_at?`<button class="primary" data-invite="${x.id}">Inviter</button>`:''}${x.active||x.open_entry?`<button class="secondary" data-clock="${x.id}">${x.open_entry?'Stemple ut':'Stemple inn'}</button>`:''}<button class="secondary" data-clock-log="${x.id}">Stemplingslogg</button><button class="secondary" data-documents="${x.id}">Dokumentarkiv</button><button class="small" data-pdf="${x.id}">PDF</button><button class="small" data-edit="${x.id}">Rediger</button><button class="${x.active?'danger':'secondary'}" data-toggle="${x.id}">${x.active?'Sett inaktiv':'Aktiver'}</button></div></td></tr>`).join('')}
function escapeHtml(value){const div=document.createElement('div');div.textContent=String(value);return div.innerHTML}
