function activateAdminPanel(panel){const button=document.querySelector(`.admin-tab[data-panel="${panel}"]`);if(!button)return;document.querySelectorAll('.admin-tab').forEach(x=>x.classList.toggle('active',x===button));document.querySelectorAll('.admin-view').forEach(x=>x.classList.toggle('hidden',x.id!==panel));if(panel==='dashboardPanel')loadDashboard().catch(error=>show(error.message));if(panel==='hmsAdminPanel')loadHms().catch(error=>show(error.message));if(panel==='sickLeaveAdminPanel')loadSickLeave(true).catch(error=>show(error.message));if(panel==='vacationAdminPanel')loadVacation(true).catch(error=>show(error.message));if(panel==='hrAdminPanel')loadHr().catch(error=>show(error.message));if(panel==='coursesAdminPanel')loadCourses().catch(error=>show(error.message));if(panel==='bulletinAdminPanel')loadEmployeeHome().catch(error=>show(error.message));if(panel==='rosterAdminPanel'){rosterWeekStart=rosterMonday();loadRoster().catch(error=>show(error.message))}if(panel==='stampingPanel')loadStamping(0).catch(error=>show(error.message));if(panel==='approvalPanel')loadMonthOverview().catch(error=>show(error.message));if(panel==='qrPanel')loadClock().catch(error=>show(error.message))}
document.querySelectorAll('.admin-tab').forEach(button=>button.onclick=()=>activateAdminPanel(button.dataset.panel));
function localDate(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Oslo'}).format(new Date())}
function dateTimeLocal(value){const parts=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Oslo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(value)).reduce((o,p)=>(o[p.type]=p.value,o),{});return `${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}`}
function osloWallToIso(value){const [date,time]=value.split('T'),[year,month,day]=date.split('-').map(Number),[hour,minute]=time.split(':').map(Number),wanted=Date.UTC(year,month-1,day,hour,minute);let guess=wanted;for(let i=0;i<3;i++){const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Oslo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(guess)).reduce((o,x)=>(o[x.type]=Number(x.value)||x.value,o),{});const shown=Date.UTC(p.year,p.month-1,p.day,p.hour,p.minute);guess+=wanted-shown}return new Date(guess).toISOString()}
function approvalSource(value){return({location:'Posisjonskontroll',qr:'QR-kode',manual:'Manuell',automatic:'Automatisk'})[value]||value}
function rosterDelta(value){if(value===null||value===undefined)return null;if(value===0)return '0 min';return `${value>0?'+':'−'}${Math.abs(value)} min`}
function rosterDeviationHtml(entry){const match=entry.roster_match;if(!match)return '<span class="muted">–</span>';if(match.status==='unplanned')return '<div class="roster-deviation warning"><strong>Ikke planlagt</strong><small>Ingen vakt i publisert vaktliste</small></div>';const planned=`${rosterTime(match.planned.start_time)}–${rosterTime(match.planned.end_time)}`;if(match.status==='match')return `<div class="roster-deviation ok"><strong>Plan ${planned}</strong><small>Som planlagt</small></div>`;const parts=[`Inn ${rosterDelta(match.start_delta_minutes)}`,match.end_delta_minutes===null?'Ut pågår':`ut ${rosterDelta(match.end_delta_minutes)}`];return `<div class="roster-deviation warning"><strong>Plan ${planned}</strong><small>${parts.join(' · ')}</small></div>`}
async function loadApproval(){const month=$('#approvalMonth').value,employeeId=$('#approvalEmployee').value;if(!month||!employeeId){show('Velg måned og ansatt.');return}const button=$('#loadApproval');button.disabled=true;button.textContent='Henter …';try{approvalData=await authenticated('/functions/v1/time-review-admin',{method:'POST',body:{action:'load',month,employee_id:employeeId}});renderApproval()}catch(error){show(error.message)}finally{button.disabled=false;button.textContent='Hent timer'}}
