function renderMonthOverview(){const locked=monthOverview.status==='locked',rows=monthOverview.employees||[],ready=rows.length>0&&rows.every(x=>x.status==='approved'&&x.open_entries===0);$('#monthLockStatus').textContent=locked?`Låst · revisjon ${monthOverview.revision}`:ready?'Klar for låsing':'Ikke klar for låsing';$('#monthLockMessage').textContent=locked?`Låst ${new Date(monthOverview.locked_at).toLocaleString('nb-NO',{timeZone:'Europe/Oslo'})}. Rapportgrunnlaget kan ikke endres.`:rows.length?`${rows.filter(x=>x.status==='approved').length} av ${rows.length} ansatte er godkjent.`:'Ingen registreringer i denne måneden.';const button=$('#lockMonth');button.classList.toggle('hidden',locked);button.disabled=!ready;$('#monthApprovalRows').innerHTML=rows.length?`<table><thead><tr><th>Ansatt</th><th>Registreringer</th><th>Timer</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${escapeHtml(x.employee_number)} · ${escapeHtml(x.full_name)}</strong></td><td>${x.entries}${x.open_entries?` · ${x.open_entries} åpne`:''}</td><td>${hours(x.hours)}</td><td><span class="status ${x.status==='approved'||x.status==='locked'?'active':''}">${x.status==='locked'?'Låst':x.status==='approved'?'Godkjent':'Åpen'}</span></td><td><button class="small" data-review-employee="${x.id}">Vis timer</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Ingen registreringer i denne måneden.</div>'}
function renderApproval(){const locked=approvalData.status==='locked',approved=approvalData.status==='approved',entries=approvalData.entries||[],open=entries.some(e=>!e.ended_at);$('#approvalStatus').textContent=locked?'Låst':approved?'Godkjent':'Åpen';$('#approvalMessage').textContent=locked?'Måneden er låst og kan ikke endres.':approved?'Måneden er godkjent. En korrigering åpner godkjenningen på nytt.':open?'En åpen registrering må stemples ut før måneden kan godkjennes.':'Klar for kontroll og godkjenning.';$('#approvalHours').textContent=hours(entries.reduce((s,e)=>s+durationHours(e),0));$('#approvalEmpty').classList.toggle('hidden',entries.length>0);$('#approvalRows').innerHTML=entries.map(e=>`<tr class="${e.roster_match?.status==='deviation'||e.roster_match?.status==='unplanned'?'time-deviation-row':''}"><td>${formatDay(e.started_at)}<small class="stamp-reference">${stampReference(e)}</small></td><td>${formatTime(e.started_at)}</td><td>${e.ended_at?formatTime(e.ended_at):'<span class="status">Pågår</span>'}</td><td>${e.ended_at?hours(durationHours(e)):'–'}</td><td>${rosterDeviationHtml(e)}</td><td>${approvalSource(e.source)}${e.auto_clocked_out?' · automatisk ut':''}</td><td>${!locked&&e.ended_at?`<div class="actions"><button class="small" data-time-edit="${e.id}">Rediger</button><button class="danger small" data-time-delete="${e.id}">Slett</button></div>`:''}</td></tr>`).join('');const approve=$('#approveMonth');approve.disabled=locked||open;approve.classList.toggle('hidden',locked);approve.textContent=approved?'Godkjenn på nytt':'Godkjenn måned';$('#approvalResult').classList.remove('hidden')}
