const payrollCategories=[{key:'ordinary_hours',category:'ordinary',fallback:'Timelønn'},{key:'evening_hours',category:'evening',fallback:'Kveldstillegg'},{key:'night_hours',category:'night',fallback:'Nattillegg'},{key:'weekend_hours',category:'weekend',fallback:'Helgetillegg'},{key:'sick_pay_hours',category:'sick_pay',fallback:'Sykepenger'},{key:'overtime_40_hours',category:'overtime_40',fallback:'Overtidstillegg 40 %'},{key:'overtime_100_hours',category:'overtime_100',fallback:'Overtidstillegg 100 %'}];
function payrollSetting(row,item){const setting=row?.payroll_codes?.[item.category]||{};return{code:setting.code||'',label:setting.label||item.fallback}}
function payrollType(row,item){const setting=payrollSetting(row,item);return `${setting.code?`${setting.code} `:''}${setting.label}`}
function payrollNumber(value){return Number(value||0).toLocaleString('nb-NO',{minimumFractionDigits:2,maximumFractionDigits:2})}
function payrollPeriod(month){const [year,m]=month.split('-').map(Number),last=new Date(Date.UTC(year,m,0)).getUTCDate();return `01.${String(m).padStart(2,'0')}.${year} - ${String(last).padStart(2,'0')}.${String(m).padStart(2,'0')}.${year}`}
function payrollLines(rows){return rows.flatMap(row=>payrollCategories.filter(item=>Number(row[item.key]||0)!==0).map(item=>({employee_number:row.employee_number,employee_name:row.employee_name,type:payrollType(row,item),code:payrollSetting(row,item).code,label:payrollSetting(row,item).label,amount:Number(row[item.key]||0),category:item.category}))) }
async function loadPayrollReport(){const month=$('#payrollReportMonth').value,button=$('#loadPayrollReport');button.disabled=true;button.textContent='Henter …';try{payrollReport=await authenticated('/functions/v1/monthly-report-admin',{method:'POST',body:{action:'load',month}});renderPayrollReport()}catch(error){show(error.message)}finally{button.disabled=false;button.textContent='Hent låst rapport'}}
function renderPayrollReport(){const accountant=payrollReport.recipients.find(x=>x.recipient_type==='accountant'),admin=payrollReport.recipients.find(x=>x.recipient_type==='admin');$('#accountantEmail').value=accountant?.email||'';$('#removeAccountant').classList.toggle('hidden',!accountant);if(!payrollReport.locked){$('#payrollReportResult').classList.add('hidden');show('Måneden er ikke låst ennå.');return}const rows=payrollReport.rows||[],lines=payrollLines(rows),period=payrollPeriod(payrollReport.month),recipients=[admin?.email,accountant?.email].filter(Boolean).join(', ');$('#payrollReportTitle').textContent=`Lønnsrapport ${payrollReport.month} · revisjon ${payrollReport.lock.revision}`;$('#payrollReportPeriod').textContent=`Periode: ${period}`;$('#payrollRecipients').textContent=`Rapportmottakere: ${recipients}`;$('#payrollPrintTitle').textContent=`Lønnsrapport for perioden ${period}`;$('#payrollPrintMeta').textContent=`Låst rapport · revisjon ${payrollReport.lock.revision}`;let previous='';$('#payrollReportRows').innerHTML=lines.map(line=>{const employee=`${line.employee_number} ${line.employee_name}`,start=employee!==previous;previous=employee;return `<tr class="${start?'employee-start':''}"><td><strong>${escapeHtml(employee)}</strong></td><td>${escapeHtml(line.type)}</td><td class="numeric">${payrollNumber(line.amount)}</td></tr>`}).join('');$('#payrollReportTotal').innerHTML=payrollCategories.map(item=>{const total=rows.reduce((sum,row)=>sum+Number(row[item.key]||0),0);if(!total)return'';return `<tr><td><strong>${escapeHtml(payrollType(rows[0],item))}</strong></td><td class="numeric"><strong>${payrollNumber(total)}</strong></td></tr>`}).join('');$('#payrollReportResult').classList.remove('hidden')}
function csvCell(value){return `"${String(value??'').replaceAll('"','""')}"`}
