const followupAddDays=(date,days)=>{const value=new Date(`${date}T12:00:00Z`);value.setUTCDate(value.getUTCDate()+days);return value.toISOString().slice(0,10)};
const followupActivityLabels={contact:'Kontakt / samtale',dialog1:'Dialogmøte 1',activity_review:'Vurdering ved 8 uker',nav_dialog2:'NAV dialogmøte 2',nav_dialog3:'NAV dialogmøte 3',plan_shared_sick_note:'Plan delt med sykmelder',plan_shared_nav:'Plan delt med NAV',employee_response:'Tilbakemelding fra ansatt',other:'Annet'};
function followupEmployee(item){return sickFollowupData.employees.find(employee=>employee.id===item.employee_id)||{full_name:'Ukjent ansatt',employee_number:''}}
function followupLatestPlan(caseId){return (sickFollowupData.plans||[]).filter(plan=>plan.case_id===caseId).sort((a,b)=>b.version-a.version)[0]||null}
function followupTasks(item){const activities=(sickFollowupData.activities||[]).filter(row=>row.case_id===item.id),plan=followupLatestPlan(item.id),today=localDate(),tasks=[{key:'plan',label:'Oppfølgingsplan',date:followupAddDays(item.start_date,28),done:!item.followup_plan_required||Boolean(plan?.shared_with_sick_note_at)},{key:'dialog1',label:'Dialogmøte 1',date:followupAddDays(item.start_date,49),done:!item.dialog1_required||activities.some(row=>row.activity_type==='dialog1')},{key:'activity',label:'Aktivitetsvurdering',date:followupAddDays(item.start_date,56),done:activities.some(row=>row.activity_type==='activity_review')},{key:'nav2',label:'NAV dialogmøte 2',date:followupAddDays(item.start_date,182),done:activities.some(row=>row.activity_type==='nav_dialog2')},{key:'week39',label:'NAV-informasjon uke 39',date:followupAddDays(item.start_date,273),done:false,info:true},{key:'week52',label:'Maksdato nærmer seg',date:followupAddDays(item.start_date,364),done:false,info:true}];return tasks.map(task=>({...task,overdue:!task.done&&!task.info&&task.date<today,soon:!task.done&&task.date>=today&&task.date<=followupAddDays(today,7)}))}
function renderSickFollowup(){renderSickLeave();const active=(sickFollowupData.cases||[]).filter(item=>item.status==='active'),allTasks=active.flatMap(item=>followupTasks(item)),overdue=allTasks.filter(task=>task.overdue).length,soon=allTasks.filter(task=>task.soon).length;$('#sickFollowupSummary').innerHTML=`<div class="${overdue?'attention':''}"><span>Forfalt</span><strong>${overdue}</strong></div><div class="${soon?'attention':''}"><span>Neste 7 dager</span><strong>${soon}</strong></div><div><span>Aktive saker</span><strong>${active.length}</strong></div><div><span>Avsluttede</span><strong>${(sickFollowupData.cases||[]).length-active.length}</strong></div>`;const cases=sickFollowupData.cases||[];$('#sickFollowupCases').innerHTML=cases.length?cases.map(item=>{const employee=followupEmployee(item),tasks=followupTasks(item),next=tasks.find(task=>!task.done&&task.date>=localDate())||tasks.find(task=>!task.done),overdueCount=tasks.filter(task=>task.overdue).length;return `<button type="button" class="followup-case ${item.status==='closed'?'closed':''}" data-followup-case="${item.id}"><span><strong>${escapeHtml(employee.employee_number)} · ${escapeHtml(employee.full_name)}</strong><small>${displayDate(item.start_date)}–${displayDate(item.current_end_date)} · ${item.sick_leave_percentage} % sykmeldt</small></span><span class="followup-case-next ${overdueCount?'overdue':''}">${overdueCount?`${overdueCount} forfalt`:item.status==='closed'?'Avsluttet':next?`${escapeHtml(next.label)} · ${displayDate(next.date)}`:'Ingen åpne frister'}</span><b>›</b></button>`}).join(''):'<p class="muted">Ingen godkjente sykmeldinger krever oppfølging.</p>'}
function fillFollowupDialog(){const item=sickFollowupData.cases.find(row=>row.id===activeFollowupCaseId);if(!item)return;const employee=followupEmployee(item),plan=followupLatestPlan(item.id),activities=(sickFollowupData.activities||[]).filter(row=>row.case_id===item.id),measures=(sickFollowupData.measures||[]).filter(row=>row.case_id===item.id);$('#followupEmployeeName').textContent=employee.full_name;$('#followupCasePeriod').textContent=`${employee.employee_number} · ${displayDate(item.start_date)}–${displayDate(item.current_end_date)}`;$('#followupCaseId').value=item.id;$('#followupPercentage').value=item.sick_leave_percentage;$('#followupStatus').value=item.status;$('#followupNextDate').value=item.next_followup_date||'';$('#followupPlanRequired').checked=item.followup_plan_required;$('#followupPlanReason').value=item.followup_plan_exemption_reason||'';$('#followupDialogRequired').checked=item.dialog1_required;$('#followupDialogReason').value=item.dialog1_exemption_reason||'';updateFollowupRequirementFields();const tasks=followupTasks(item);$('#followupTimeline').innerHTML=tasks.map(task=>`<div class="followup-step ${task.done?'done':task.overdue?'overdue':task.soon?'soon':''}"><span>${task.done?'✓':task.overdue?'!':'•'}</span><strong>${escapeHtml(task.label)}</strong><small>${displayDate(task.date)}</small></div>`).join('');['ordinary_tasks','work_ability','accommodation_options','agreed_measures','external_assistance','return_goal'].forEach((key,index)=>{const ids=['#followupOrdinaryTasks','#followupWorkAbility','#followupAccommodation','#followupAgreedMeasures','#followupExternalAssistance','#followupReturnGoal'];$(ids[index]).value=plan?.[key]||''});$('#followupReviewDate').value=plan?.next_review_date||'';$('#followupSharedSickNote').checked=Boolean(plan?.shared_with_sick_note_at);$('#followupSharedNav').checked=Boolean(plan?.shared_with_nav_at);$('#followupEmployeeAck').checked=Boolean(plan?.employee_acknowledged_at);$('#followupPlanVersion').textContent=plan?`Siste lagrede versjon: ${plan.version} · ${displayDate(String(plan.created_at).slice(0,10))}`:'Ingen plan er lagret ennå.';$('#followupMeasures').innerHTML=measures.length?measures.map(row=>`<article class="followup-log"><div><strong>${escapeHtml(row.title)}</strong><small>${row.description?escapeHtml(row.description):''}${row.evaluation_date?` · Evalueres ${displayDate(row.evaluation_date)}`:''}</small></div><select data-followup-measure="${row.id}"><option value="planned" ${row.status==='planned'?'selected':''}>Planlagt</option><option value="active" ${row.status==='active'?'selected':''}>Aktiv</option><option value="completed" ${row.status==='completed'?'selected':''}>Fullført</option><option value="cancelled" ${row.status==='cancelled'?'selected':''}>Avbrutt</option></select></article>`).join(''):'<p class="muted">Ingen tiltak registrert.</p>';$('#followupActivities').innerHTML=activities.length?activities.map(row=>`<article class="followup-log"><div><strong>${escapeHtml(row.title)}</strong><small>${displayDate(row.occurred_on)} · ${escapeHtml(followupActivityLabels[row.activity_type]||row.activity_type)}${row.participants?` · ${escapeHtml(row.participants)}`:''}</small>${row.summary?`<p>${escapeHtml(row.summary)}</p>`:''}</div></article>`).join(''):'<p class="muted">Ingen kontakt eller møter registrert.</p>';$('#followupActivityDate').value=localDate()}
function updateFollowupRequirementFields(){$('#followupPlanReasonWrap').classList.toggle('hidden',$('#followupPlanRequired').checked);$('#followupDialogReasonWrap').classList.toggle('hidden',$('#followupDialogRequired').checked)}
async function reloadFollowup(){sickFollowupData=await authenticated('/functions/v1/sick-followup');renderSickFollowup();if(activeFollowupCaseId)fillFollowupDialog()}
