$('#adminSickRequests').onclick=async event=>{const button=event.target.closest('[data-sick-handle]');if(!button)return;const status=button.dataset.status,id=button.dataset.sickHandle,comment=document.querySelector(`[data-sick-comment="${id}"]`).value.trim();if(status==='rejected'&&comment.length<3)return show('Skriv en kort kommentar ved avvisning.');if(!confirm(status==='approved'?'Godkjenne fraværet og føre 8 timer per aktuell hverdag?':'Avvise fraværsmeldingen?'))return;button.disabled=true;try{await authenticated('/functions/v1/sick-leave',{method:'PATCH',body:{action:'handle',id,status,admin_comment:comment}});show(status==='approved'?'Fraværet er godkjent og ført i timelisten.':'Fraværet er avvist.');await loadSickLeave(true)}catch(error){show(error.message)}finally{button.disabled=false}};
