$('#followupPlanForm').onsubmit=async event=>{event.preventDefault();const button=event.submitter,original=button.textContent;button.disabled=true;button.textContent='Lagrer …';try{await authenticated('/functions/v1/sick-followup',{method:'POST',body:{action:'save_plan',case_id:activeFollowupCaseId,ordinary_tasks:$('#followupOrdinaryTasks').value.trim(),work_ability:$('#followupWorkAbility').value.trim(),accommodation_options:$('#followupAccommodation').value.trim(),agreed_measures:$('#followupAgreedMeasures').value.trim(),external_assistance:$('#followupExternalAssistance').value.trim(),return_goal:$('#followupReturnGoal').value.trim(),next_review_date:$('#followupReviewDate').value,shared_with_sick_note:$('#followupSharedSickNote').checked,shared_with_nav:$('#followupSharedNav').checked,employee_acknowledged:$('#followupEmployeeAck').checked}});show('Ny versjon av oppfølgingsplanen er lagret.');await reloadFollowup()}catch(error){show(error.message)}finally{button.disabled=false;button.textContent=original}};
$('#followupActivityForm').onsubmit=async event=>{event.preventDefault();const button=event.submitter,original=button.textContent;button.disabled=true;button.textContent='Lagrer …';try{await authenticated('/functions/v1/sick-followup',{method:'POST',body:{action:'add_activity',case_id:activeFollowupCaseId,activity_type:$('#followupActivityType').value,occurred_on:$('#followupActivityDate').value,title:$('#followupActivityTitle').value.trim(),participants:$('#followupActivityParticipants').value.trim(),summary:$('#followupActivitySummary').value.trim(),next_followup_date:$('#followupActivityNext').value,sick_note_consent:$('#followupSickNoteConsent').checked}});event.target.reset();show('Aktiviteten er lagret.');await reloadFollowup()}catch(error){show(error.message)}finally{button.disabled=false;button.textContent=original}};
$('#followupMeasureForm').onsubmit=async event=>{event.preventDefault();const button=event.submitter,original=button.textContent;button.disabled=true;button.textContent='Lagrer …';try{await authenticated('/functions/v1/sick-followup',{method:'POST',body:{action:'add_measure',case_id:activeFollowupCaseId,title:$('#followupMeasureTitle').value.trim(),description:$('#followupMeasureDescription').value.trim(),responsible_party:$('#followupMeasureResponsible').value,start_date:$('#followupMeasureStart').value,evaluation_date:$('#followupMeasureEvaluation').value,status:'planned'}});event.target.reset();show('Tiltaket er lagt til.');await reloadFollowup()}catch(error){show(error.message)}finally{button.disabled=false;button.textContent=original}};
