$('#rosterWeek').onclick=async event=>{const quick=event.target.closest('[data-roster-quick-date]'),add=event.target.closest('[data-roster-add]'),edit=event.target.closest('[data-roster-edit]'),remove=event.target.closest('[data-roster-delete]');if(quick)return openRosterShift(quick.dataset.rosterQuickDate,null,quick.dataset.rosterQuickType,quick.dataset.rosterQuickStart,quick.dataset.rosterQuickEnd,quick.dataset.rosterQuickLabel);if(add)return openRosterShift(add.dataset.rosterAdd);if(edit){const shift=rosterData.shifts.find(x=>x.id===edit.dataset.rosterEdit);return openRosterShift(shift.work_date,shift)}if(remove){if(!confirm('Fjerne denne vakten?'))return;remove.disabled=true;try{await authenticated(`/functions/v1/roster?week=${rosterWeekStart}`,{method:'DELETE',body:{action:'delete_shift',id:remove.dataset.rosterDelete}});show('Vakten er fjernet.');await loadRoster()}catch(error){show(error.message)}finally{remove.disabled=false}}};
$('#cancelRosterShift').onclick=()=>$('#rosterShiftDialog').close();$('#rosterShiftForm').onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{await authenticated(`/functions/v1/roster?week=${rosterWeekStart}`,{method:'POST',body:{action:'save_shift',id:$('#rosterShiftId').value||undefined,employee_id:$('#rosterShiftEmployee').value,work_date:$('#rosterShiftDate').value,shift_type:$('#rosterShiftType').value,start_time:$('#rosterShiftStart').value,end_time:$('#rosterShiftEnd').value}});$('#rosterShiftDialog').close();show('Vakten er lagret.');await loadRoster()}catch(error){show(error.message)}finally{button.disabled=false}};
