$('#deactivateRoster').onclick=async()=>{if(!confirm('Sette vaktlisten inaktiv? Den skjules for ansatte.'))return;const button=$('#deactivateRoster');button.disabled=true;try{await authenticated(`/functions/v1/roster?week=${rosterWeekStart}`,{method:'PATCH',body:{action:'inactive'}});show('Vaktlisten er satt inaktiv.');await loadRoster()}catch(error){show(error.message)}finally{button.disabled=false}};
