// ADMIN register: one durable reference per attendance interval, including deleted entries.
function stampReference(entry){return entry.reference_no!=null?'ST-'+String(entry.reference_no).padStart(6,'0'):'–'}
let stampingData=null,stampingPage=0,stampingLoading=false,pendingDeleteStamp=null;
$('#stampingMonth').value=localMonth();
async function loadStamping(page=0){
  if(stampingLoading)return;
  stampingLoading=true;$('#loadStamping').disabled=true;$('#stampingPrevious').disabled=true;$('#stampingNext').disabled=true;$('#stampingMessage').textContent='Henter stemplinger …';
  try{
    const data=await authenticated('/functions/v1/time-review-admin',{method:'POST',body:{action:'register',month:$('#stampingMonth').value,employee_id:$('#stampingEmployee').value,status:$('#stampingStatus').value,reference:$('#stampingReference').value.trim(),page}});
    stampingData=data;stampingPage=data.page;
    const select=$('#stampingEmployee'),selected=select.value;
    select.innerHTML='<option value="">Alle ansatte</option>'+data.employees.map(x=>`<option value="${escapeHtml(x.id)}">${escapeHtml(x.employee_number)} · ${escapeHtml(x.full_name)}</option>`).join('');select.value=selected;
    $('#stampingRows').innerHTML=data.entries.map(entry=>{
      const history=data.events.filter(x=>x.entry_id===entry.id),deleted=Boolean(entry.deleted_at),status=deleted?'Slettet':!entry.ended_at?'Innstemplet':entry.locked?'Låst måned':'Avsluttet';
      return `<article class="card stamp-card ${deleted?'stamp-deleted':''}"><div class="stamp-card-head"><div><strong>${escapeHtml(entry.employee_name)}</strong><small class="stamp-reference">${stampReference(entry)} · Ansatt ${escapeHtml(entry.employee_number)}</small></div><span class="status ${deleted?'':'active'}">${status}</span></div><div class="stamp-times"><div><span>Inn</span><strong>${clockStampTime(entry.started_at)}</strong></div><div><span>Ut</span><strong>${clockStampTime(entry.ended_at)}</strong></div><div><span>${deleted?'Slettet varighet':'Timer'}</span><strong>${entry.ended_at?hours(durationHours(entry)):'Pågår'}</strong></div></div><p class="hint">${escapeHtml(approvalSource(entry.source))}${entry.auto_clocked_out?' · Automatisk utstemplet':''}</p>${deleted?`<p class="stamp-deletion">Slettet ${clockStampTime(entry.deleted_at)} av ${escapeHtml(entry.deleted_by_name)}<br>Begrunnelse: ${escapeHtml(entry.deletion_reason)}</p>`:''}${entry.note?`<p class="hint">${escapeHtml(entry.note)}</p>`:''}<div class="actions">${!deleted&&entry.ended_at&&!entry.locked?`<button type="button" class="danger small" data-stamp-delete="${entry.id}">Slett</button>`:''}${!deleted&&!entry.ended_at?'<span class="hint">Stemple ut under Ansatte før eventuell sletting.</span>':''}</div><details class="stamp-history"><summary>Hendelser og endringer (${history.length})</summary>${history.map(x=>`<div class="clock-log-row"><div><strong>${escapeHtml(({clock_in:'Stemplet inn',clock_out:'Stemplet ut',manual_clock_in:'ADMIN stemplet inn',manual_clock_out:'ADMIN stemplet ut',correct_time_entry:'Korrigert',delete_time_entry:'Slettet fra timelisten'})[x.action]||x.action)}</strong><small>${clockStampTime(x.at)} · ${escapeHtml(x.actor)}</small>${x.reason?`<p>Begrunnelse: ${escapeHtml(x.reason)}</p>`:''}${x.before?`<small>Før: ${clockStampTime(x.before.started_at)} – ${clockStampTime(x.before.ended_at)}</small>`:''}${x.after?`<small>Etter: ${clockStampTime(x.after.started_at)} – ${clockStampTime(x.after.ended_at)}</small>`:''}</div></div>`).join('')||'<p class="hint">Ingen lagrede endringshendelser.</p>'}</details></article>`;
    }).join('')||'<div class="card empty">Ingen stemplinger passer filtrene.</div>';
    $('#stampingMessage').textContent=data.events_truncated?'Endringshistorikken er avkortet. Søk på referansekoden for å se historikken til én stempling.':'Tidspunkter vises i norsk tid, med sekunder.';
    $('#stampingPage').textContent=`Side ${data.page+1} · ${data.entries.length} registreringer`;
    $('#stampingPrevious').disabled=data.page===0;$('#stampingNext').disabled=!data.has_more;
  }catch(error){stampingData=null;$('#stampingRows').textContent='';$('#stampingPage').textContent='';$('#stampingMessage').textContent=error.message}
  finally{stampingLoading=false;$('#loadStamping').disabled=false}
}
$('#stampingFilters').onsubmit=event=>{event.preventDefault();loadStamping(0)};
$('#stampingPrevious').onclick=()=>loadStamping(Math.max(0,stampingPage-1));
$('#stampingNext').onclick=()=>loadStamping(stampingPage+1);
$('#stampingRows').onclick=event=>{const button=event.target.closest('[data-stamp-delete]');if(button){const entry=stampingData?.entries.find(x=>x.id===button.dataset.stampDelete);if(entry)openDeleteStamp(entry,entry.employee_name)}};
function openDeleteStamp(entry,name){
  if(!entry||!entry.ended_at||entry.deleted_at||entry.locked)return;
  pendingDeleteStamp={...entry};$('#deleteStampSummary').textContent=`${name} · ${stampReference(entry)} · ${clockStampTime(entry.started_at)} – ${clockStampTime(entry.ended_at)} (${hours(durationHours(entry))})`;
  $('#deleteStampReason').value='';$('#deleteStampError').classList.add('hidden');$('#deleteStampDialog').showModal();$('#deleteStampReason').focus();
}
$('#cancelDeleteStamp').onclick=()=>$('#deleteStampDialog').close();
$('#deleteStampForm').onsubmit=async event=>{
  event.preventDefault();if(!pendingDeleteStamp||$('#confirmDeleteStamp').disabled)return;
  const entry=pendingDeleteStamp,reason=$('#deleteStampReason').value.trim(),errorBox=$('#deleteStampError');
  if(reason.length<3){errorBox.textContent='Skriv en begrunnelse på minst tre tegn.';errorBox.classList.remove('hidden');return}
  $('#confirmDeleteStamp').disabled=true;$('#cancelDeleteStamp').disabled=true;
  try{
    await authenticated('/functions/v1/time-review-admin',{method:'POST',body:{action:'delete',entry_id:entry.id,started_at:entry.started_at,ended_at:entry.ended_at,reason}});
    pendingDeleteStamp=null;$('#deleteStampDialog').close();show(`${stampReference(entry)} er slettet fra timelisten. Historikken er beholdt.`);
    const refreshes=[loadEmployees(),loadMonthOverview()];
    if($('#approvalEmployee').value)refreshes.push(loadApproval());
    if(!$('#stampingPanel').classList.contains('hidden'))refreshes.push(loadStamping(stampingPage));
    if($('#clockLogDialog').open)refreshes.push(loadClockLog());
    const results=await Promise.allSettled(refreshes);if(results.some(x=>x.status==='rejected'))show('Stemplingen er slettet. Oppdater siden for å hente nye summer.');
  }catch(error){errorBox.textContent=error.message;errorBox.classList.remove('hidden')}
  finally{$('#confirmDeleteStamp').disabled=false;$('#cancelDeleteStamp').disabled=false}
};
